t.script:
                window.addEventListener("load", function () {
                    setTimeout(function () {
                        initLessonProgramCalendar();
                    }, 500);
                });
            
                function initLessonProgramCalendar() {
                    var calendarEl = document.getElementById("lesson-program-calendar");
            
                    if (!calendarEl) {
                        console.error("Calendar container not found");
                        return;
                    }
            
                    if (typeof FullCalendar === "undefined") {
                        console.error("FullCalendar is not loaded");
                        calendarEl.innerHTML = "
Calendar could not load. Please refresh the page.";
                        return;
                    }
            
                    var programId = document.getElementById("lesson_program_id").value;
                    var sessionCount = parseInt(document.getElementById("session_count").value, 10);
                    var addToCartButton = document.getElementById("lesson-program-add-to-cart");
                    var selectedInput = document.getElementById("selected_booking_ids");
                    var selectionInfo = document.getElementById("selection-info");
                    var selectedDateLabel = document.getElementById("selected-date-label");
                    var availableTimesPanel = document.getElementById("available-times-panel");
                    var messageBox = document.getElementById("lesson-program-message");
            
                    var selectedBookingIds = [];
            
                    function showMessage(message, type) {
                        if (!type) {
                            type = "warning";
                        }
            
                        messageBox.className = "alert alert-" + type;
                        messageBox.innerText = message;
                        messageBox.classList.remove("d-none");
            
                        setTimeout(function () {
                            messageBox.classList.add("d-none");
                        }, 4000);
                    }
            
                    function refreshButtonState() {
                        selectedInput.value = JSON.stringify(selectedBookingIds);
            
                        var remaining = sessionCount - selectedBookingIds.length;
            
                        if (remaining > 0) {
                            selectionInfo.innerText = "Please select " + remaining + " more lesson time(s).";
                            addToCartButton.style.opacity = "0.5";
                            addToCartButton.style.pointerEvents = "none";
                            addToCartButton.classList.add("disabled");
                        } else {
                            selectionInfo.innerText = "You selected all " + sessionCount + " lesson time(s).";
                            addToCartButton.style.opacity = "1";
                            addToCartButton.style.pointerEvents = "auto";
                            addToCartButton.classList.remove("disabled");
                        }
                    }
            
                    var calendar = new FullCalendar.Calendar(calendarEl, {
                        initialView: "dayGridMonth",
                        height: "auto",
                        headerToolbar: {
                            left: "prev,next today",
                            center: "title",
                            right: "dayGridMonth,timeGridWeek"
                        },
                        validRange: {
                            start: new Date().toISOString().split("T")[0]
                        },
                        events: function (fetchInfo, successCallback, failureCallback) {
                            fetch("/lesson_program/available_dates?program_id=" + programId)
                                .then(function (response) {
                                    return response.json();
                                })
                                .then(function (data) {
                                    var events = [];
            
                                    for (var date in data) {
                                        events.push({
                                            title: "",
                                            start: date,
                                            allDay: true,
                                            display: "background",
                                            className: "fc-available-date"
                                        });
                                    }
            
                                    successCallback(events);
                                })
                                .catch(function (error) {
                                    console.error("Error fetching calendar data:", error);
                                    failureCallback(error);
                                });
                        },
                        dateClick: function (info) {
                            document.querySelectorAll(".fc-daygrid-day.selected-calendar-date").forEach(function (day) {
                                day.classList.remove("selected-calendar-date");
                            });
            
                            info.dayEl.classList.add("selected-calendar-date");
            
                            var formattedDate = info.date.toLocaleDateString(undefined, {
                                weekday: "long",
                                year: "numeric",
                                month: "long",
                                day: "numeric"
                            });
            
                            selectedDateLabel.innerText = formattedDate;
                            availableTimesPanel.classList.remove("d-none");
            
                            fetch("/lesson_program/available_times?program_id=" + programId + "&date=" + info.dateStr)
                                .then(function (response) {
                                    return response.json();
                                })
                                .then(function (times) {
                                    var container = document.getElementById("available-times");
                                    container.innerHTML = "";
            
                                    if (!times.length) {
                                        container.classList.remove("lesson-times-grid");
                                        container.innerHTML = "
No available times for this date.";
                                        return;
                                    }
            
                                    container.classList.add("lesson-times-grid");
            
                                    times.forEach(function (slot) {
                                        var btn = document.createElement("button");
                                        btn.type = "button";
                                        btn.innerText = slot.time;
                                        btn.className = "lesson-time-pill btn btn-outline-primary";
                                        btn.dataset.bookingId = slot.booking_id;
            
                                        if (selectedBookingIds.indexOf(slot.booking_id) !== -1) {
                                            btn.classList.add("selected-slot");
                                        }
            
                                        btn.addEventListener("click", function () {
                                            var bookingId = parseInt(this.dataset.bookingId, 10);
                                            var existingIndex = selectedBookingIds.indexOf(bookingId);
            
                                            if (existingIndex !== -1) {
                                                selectedBookingIds.splice(existingIndex, 1);
                                                this.classList.remove("selected-slot");
                                            } else {
                                                if (selectedBookingIds.length >= sessionCount) {
                                                    showMessage("You can only select " + sessionCount + " lesson time(s).", "warning");
                                                    return;
                                                }
            
                                                selectedBookingIds.push(bookingId);
                                                this.classList.add("selected-slot");
                                            }
            
                                            refreshButtonState();
                                        });
            
                                        container.appendChild(btn);
                                    });
                                })
                                .catch(function (error) {
                                    console.error("Error fetching available times:", error);
                                    var container = document.getElementById("available-times");
                                    container.classList.remove("lesson-times-grid");
                                    container.innerHTML = "
Could not load available times.";
                                });
                        }
                    });
            
                    calendar.render();
            
                    setTimeout(function () {
                        calendar.updateSize();
                    }, 300);
            
                    refreshButtonState();
            
                    addToCartButton.addEventListener("click", function (event) {
                        event.preventDefault();
            
                        if (selectedBookingIds.length !== sessionCount) {
                            showMessage("Please select exactly " + sessionCount + " lesson time(s).", "warning");
                            return;
                        }
            
                        addToCartButton.style.opacity = "0.5";
                        addToCartButton.style.pointerEvents = "none";
                        addToCartButton.classList.add("disabled");
            
                        var formData = new FormData();
                        formData.append("program_id", programId);
                        formData.append("selected_booking_ids", JSON.stringify(selectedBookingIds));
            
                        fetch("/custom/update_lesson_program_order_line", {
                            method: "POST",
                            body: formData
                        })
                        .then(function (response) {
                            return response.json();
                        })
                        .then(function (data) {
                            if (data.success && data.redirect) {
                                window.location.href = data.redirect;
                            } else {
                                showMessage(data.error || "Could not add lesson program to cart.", "danger");
                                refreshButtonState();
                            }
                        })
                        .catch(function (error) {
                            console.error(error);
                            showMessage("An unexpected error occurred. Please try again.", "danger");
                            refreshButtonState();
                        });
                    });
                }
